contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params:
    //   initMin: value to set as MinSum
    //   dep: amount to deposit
    //   want: amount to attempt to collect
    function run(uint initMin, uint dep, uint want) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        // we need Ether available to deposit
        require(address(this).balance >= dep);
        // set up once and finalize
        c.SetMinSum(initMin); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        // deposit dep so this contract has recorded balance
        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;

        uint beforeRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        bool reverted;
        c.Collect(want); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // single simple assertion: either nothing changed when reverted, or the decreases are equal when not reverted
        assert(
            reverted
            ? (afterRecorded == beforeRecorded && afterContractBal == beforeContractBal)
            : ((beforeRecorded - afterRecorded) == (beforeContractBal - afterContractBal))
        );
    }

    receive() external payable { }
}

