// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 initMin, uint256 dep, uint256 want) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep);
        try c.SetMinSum(initMin) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: dep}() {} catch { return; }
        uint256 beforeRecorded;
        try c.balances(address(this)) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        uint beforeContractBal = address(c).balance;
        bool reverted;
        try c.Collect(want) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterRecorded;
        try c.balances(address(this)) returns (uint256 __r) { afterRecorded = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        assertTrue(reverted
            ? (afterRecorded == beforeRecorded && afterContractBal == beforeContractBal)
            : ((beforeRecorded - afterRecorded) == (beforeContractBal - afterContractBal)));
    }

    function testFuzz_run(uint256 initMin, uint256 dep, uint256 want) public {
        _run(initMin, dep, want);
    }

    receive() external payable { }
}
